<script setup>
import { Link, useForm } from "@inertiajs/vue3";
import { computed, ref } from "vue";
import EnglishBooksLayout from "@/Layouts/EnglishBooksLayout.vue";

const props = defineProps({ book: { type: Object, default: null } });
const isEditing = computed(() => !!props.book?.id);
const form = useForm({ title: props.book?.title || "", author: props.book?.author || "", cover_url: props.book?.cover_url || "", cover_image: null, status: props.book?.status || "want", difficulty: props.book?.difficulty || null, word_count: props.book?.word_count || null, page_count: props.book?.page_count || null, started_on: props.book?.started_on || "", finished_on: props.book?.finished_on || "", rating: props.book?.rating || null, memo: props.book?.memo || "" });
const preview = ref(props.book?.cover_image_url || "");
const selectCover = (event) => { const [file] = event.target.files; form.cover_image = file || null; preview.value = file ? URL.createObjectURL(file) : preview.value; };
const save = () => { const target = isEditing.value ? route("admin.englishBooks.update", props.book.id) : route("admin.englishBooks.store"); form.post(target, { forceFormData: true, onSuccess: () => form.reset() }); };
</script>

<template>
    <EnglishBooksLayout :title="isEditing ? 'Edit book — The English Shelf' : 'Add a book — The English Shelf'">
        <div class="mx-auto max-w-3xl px-5 py-10 pb-20 sm:px-8 sm:py-14"><Link :href="route('admin.englishBooks.index')" class="text-sm font-bold text-[#74665e] transition hover:text-[#c96b48]">← My shelf に戻る</Link><div class="mt-8 rounded-2xl border border-[#ded7ca] bg-[#fbf9f4] p-5 shadow-[0_8px_30px_rgba(72,55,40,0.06)] sm:p-8"><p class="text-xs font-bold uppercase tracking-[0.18em] text-[#c96b48]">{{ isEditing ? 'Edit entry' : 'New entry' }}</p><h1 class="mt-2 font-serif text-3xl font-bold text-[#25323a]">{{ isEditing ? '本を編集する' : '新しい本を加える' }}</h1><p class="mt-3 text-sm leading-6 text-[#74665e]">表紙、難易度、語数まで記録して、英語読書の軌跡を残しましょう。</p><form class="mt-8 grid gap-5 sm:grid-cols-2" @submit.prevent="save"><label class="sm:col-span-2"><span class="text-sm font-bold text-[#3d4b52]">タイトル <span class="text-rose-500">*</span></span><input v-model="form.title" class="mt-1.5 block w-full rounded-lg border-[#d6cec1] bg-white text-sm shadow-sm focus:border-[#c96b48] focus:ring-[#c96b48]" placeholder="The Great Gatsby" /><p v-if="form.errors.title" class="mt-1 text-xs text-rose-600">{{ form.errors.title }}</p></label><label><span class="text-sm font-bold text-[#3d4b52]">著者</span><input v-model="form.author" class="mt-1.5 block w-full rounded-lg border-[#d6cec1] bg-white text-sm" placeholder="F. Scott Fitzgerald" /></label><div><span class="text-sm font-bold text-[#3d4b52]">表紙画像</span><div class="mt-1.5 flex items-center gap-3"><div class="flex h-20 w-14 shrink-0 items-center justify-center overflow-hidden rounded-md bg-[#eee7db] text-[10px] font-bold text-[#8b7568]"><img v-if="preview" :src="preview" alt="選択した表紙のプレビュー" class="h-full w-full object-cover" /><span v-else>BOOK</span></div><label class="cursor-pointer rounded-lg border border-dashed border-[#c96b48] bg-[#f9ede7] px-3 py-2 text-sm font-bold text-[#a94d2e] hover:bg-[#f2ddd3]">画像を選択<input type="file" accept="image/jpeg,image/png,image/webp" class="sr-only" @change="selectCover" /></label></div><p class="mt-1 text-xs text-[#8b7568]">JPG・PNG・WebP、5MBまで</p><p v-if="form.errors.cover_image" class="mt-1 text-xs text-rose-600">{{ form.errors.cover_image }}</p></div><label><span class="text-sm font-bold text-[#3d4b52]">表紙画像URL（任意）</span><input v-model="form.cover_url" type="url" class="mt-1.5 block w-full rounded-lg border-[#d6cec1] bg-white text-sm" placeholder="https://..." /></label><label><span class="text-sm font-bold text-[#3d4b52]">読書状況</span><select v-model="form.status" class="mt-1.5 block w-full rounded-lg border-[#d6cec1] bg-white text-sm"><option value="want">読みたい</option><option value="reading">読書中</option><option value="finished">読了</option></select></label><label><span class="text-sm font-bold text-[#3d4b52]">難易度（1〜5）</span><select v-model="form.difficulty" class="mt-1.5 block w-full rounded-lg border-[#d6cec1] bg-white text-sm"><option :value="null">未設定</option><option v-for="n in 5" :key="n" :value="n">{{ n }}</option></select></label><label><span class="text-sm font-bold text-[#3d4b52]">語数</span><input v-model.number="form.word_count" type="number" min="0" class="mt-1.5 block w-full rounded-lg border-[#d6cec1] bg-white text-sm" placeholder="例: 47000" /></label><label><span class="text-sm font-bold text-[#3d4b52]">ページ数</span><input v-model.number="form.page_count" type="number" min="1" class="mt-1.5 block w-full rounded-lg border-[#d6cec1] bg-white text-sm" placeholder="例: 180" /></label><label><span class="text-sm font-bold text-[#3d4b52]">読み始めた日</span><input v-model="form.started_on" type="date" class="mt-1.5 block w-full rounded-lg border-[#d6cec1] bg-white text-sm" /></label><label><span class="text-sm font-bold text-[#3d4b52]">読了日</span><input v-model="form.finished_on" type="date" class="mt-1.5 block w-full rounded-lg border-[#d6cec1] bg-white text-sm" /></label><label><span class="text-sm font-bold text-[#3d4b52]">評価（1〜5）</span><select v-model="form.rating" class="mt-1.5 block w-full rounded-lg border-[#d6cec1] bg-white text-sm"><option :value="null">未設定</option><option v-for="n in 5" :key="n" :value="n">★ {{ n }}</option></select></label><label class="sm:col-span-2"><span class="text-sm font-bold text-[#3d4b52]">メモ</span><textarea v-model="form.memo" rows="4" class="mt-1.5 block w-full rounded-lg border-[#d6cec1] bg-white text-sm" placeholder="読んでみたい理由、感想、気になった表現など"></textarea></label><div class="sm:col-span-2 flex items-center gap-4"><button type="submit" :disabled="form.processing" class="rounded-full bg-[#c96b48] px-7 py-3 text-sm font-bold text-white shadow-sm transition hover:bg-[#ad5637] disabled:opacity-50">{{ isEditing ? '更新する' : '本棚に追加する' }}</button><Link :href="route('admin.englishBooks.index')" class="text-sm font-bold text-[#74665e] hover:text-[#c96b48]">キャンセル</Link></div></form></div></div>
    </EnglishBooksLayout>
</template>
